import React from "react";
import ReactMarkdown from "react-markdown";
import rehypeSanitize from "rehype-sanitize";
import remarkGfm from "remark-gfm";
import styled from "styled-components";

interface MarkdownRendererProps {
    content: string;
    className?: string;
}

const MarkdownContainer = styled.div`
    word-break: break-word;
    overflow-wrap: break-word;
    min-width: 0;

    p {
        margin: 0.5em 0;
    }

    pre {
        background-color: ${({ theme }) => theme.colorsBackgroundTableHeaderDefault};
        border: 1px solid ${({ theme }) => theme.colorsBorderSecondary};
        border-radius: 4px;
        padding: 12px;
        overflow-x: auto;
        margin: 0.5em 0;

        code {
            background: none;
            padding: 0;
            border: none;
            font-size: 0.85em;
        }
    }

    code {
        background-color: ${({ theme }) => theme.colorsBackgroundTableHeaderDefault};
        border-radius: 3px;
        padding: 2px 4px;
        font-size: 0.85em;
        font-family: monospace;
    }

    table {
        border-collapse: collapse;
        width: 100%;
        margin: 0.5em 0;
        overflow-x: auto;
        display: block;
    }

    th,
    td {
        border: 1px solid ${({ theme }) => theme.colorsBorderSecondary};
        padding: 6px 12px;
        text-align: left;
    }

    th {
        background-color: ${({ theme }) => theme.colorsBackgroundDefault};
    }

    ul,
    ol {
        padding-left: 1.5em;
    }

    blockquote {
        border-left: 3px solid ${({ theme }) => theme.colorsBorderSecondary};
        margin: 0.5em 0;
        padding-left: 12px;
        color: ${({ theme }) => theme.colorsTextSecondaryDefault};
    }

    a {
        color: ${({ theme }) => theme.colorsTextLink};
    }
`;

/**
 * MarkdownRenderer component for safely rendering markdown content from LLM responses.
 * Uses react-markdown with GitHub Flavored Markdown support and content sanitization.
 *
 * @param content - The markdown string to render
 * @param className - Optional CSS class name for additional styling
 */
const MarkdownRenderer: React.FC<MarkdownRendererProps> = ({ content, className }) => {
    return (
        <MarkdownContainer className={className}>
            <ReactMarkdown remarkPlugins={[remarkGfm]} rehypePlugins={[rehypeSanitize]}>
                {content}
            </ReactMarkdown>
        </MarkdownContainer>
    );
};

export default MarkdownRenderer;
